// Safe defaults: image_preview renders actual graphics but NEVER uploads assets or appends queue rows.
// Production enabling requires an owner-reviewed visual, explicit toggle below, and activating this workflow.
// Modes: image_preview | draft_write_enabled
return [{json:{mode:'image_preview',maxPerDay:2,slotTimes:['10:00','15:00'],approvalRequired:true,timezone:'America/Denver',previewOnly:true}}];

const cfg=$('Configuration and Safety Mode').first().json;
const rows=$input.all().map(i=>i.json);
const normal=s=>String(s||'').trim().replace(/\/+$/,'').toLowerCase();
const fmt=new Intl.DateTimeFormat('en-US',{timeZone:'America/Denver',year:'numeric',month:'2-digit',day:'2-digit'});
const ps=Object.fromEntries(fmt.formatToParts(new Date()).map(p=>[p.type,p.value]));
const tomorrow=new Date(Date.UTC(Number(ps.year),Number(ps.month)-1,Number(ps.day)+1,12)).toISOString().slice(0,10);
const existing=rows.filter(r=>String(r.ContentTitle||'').startsWith('[Explainer]')&&!['Cancelled','Failed'].includes(String(r.Status||'')));
const scheduled=existing.filter(r=>String(r.ScheduledFor||'').startsWith(tomorrow));
const current=Math.min(2,scheduled.length);
const available=Math.max(0,cfg.maxPerDay-current);
if(!available)return [];
const existingArticleLinks=new Set(existing.map(r=>normal(r.ArticleURL)).filter(Boolean));
const existingIds=new Set(existing.map(r=>String(r.QueueID||'')));
const eligible=rows.filter(r=>{
 const url=String(r.ArticleURL||'').trim();
 return r.QueueID&&!String(r.ContentTitle||'').startsWith('[Explainer]')
 &&String(r.ArticleStatus||'').trim()==='Published'
 &&/^https:\/\/launchaiworks\.com\/[a-z0-9][^\s]*\/?$/i.test(url)
 &&!url.includes('/wp-admin/')&&!existingArticleLinks.has(normal(url))
 &&['News','Tool','WorkingOn'].includes(String(r.ContentType||'').trim())
 &&!['Failed','Cancelled'].includes(String(r.Status||''));
});
const weight=r=>({WorkingOn:2000,Tool:1000,News:0}[r.ContentType]||0)+Math.min(999,Number(String(r.QueueID||'').match(/^Q-(\d+)$/)?.[1]||0));

const lanes=['WorkingOn','Tool','News'].map(kind=>eligible.filter(r=>r.ContentType===kind).sort((a,b)=>weight(b)-weight(a)));
const ordered=[];
for(let i=0;i<eligible.length;i++){
 let any=false;
 for(const lane of lanes)if(i<lane.length){ordered.push(lane[i]);any=true}
 if(!any)break;
}
const chosen=[],urls=new Set();
for(const r of ordered){
 const url=normal(r.ArticleURL);if(urls.has(url))continue;urls.add(url);
 const slug=url.split('/').filter(Boolean).pop();
 const qid='EX-'+tomorrow.replace(/-/g,'')+'-'+String(r.QueueID).replace(/[^a-z0-9]/gi,'');
 if(existingIds.has(qid))continue;
 chosen.push({json:{_mode:cfg.mode,_available:available,_maxPerDay:cfg.maxPerDay,_targetDay:tomorrow,_articleUrl:String(r.ArticleURL).trim(),_slug:slug,_parentId:String(r.QueueID),_contentType:r.ContentType,_sourceUrl:String(r.SourceURL||r.ArticleURL),_headline:String(r.ContentTitle||'').replace(/^\[[^\]]+\]\s*/,''),_queueId:qid,_slotTimes:cfg.slotTimes,_brand:'Launch AI Works',_sourceStatus:r.Status}});
 if(chosen.length>=Math.min(12,available*4))break;
}
return chosen;

const originals=$('Select Two Published Articles').all().map(i=>i.json);
const posts=$input.all().map(i=>i.json).flatMap(x=>Array.isArray(x)?x:[x]);
const decode=s=>String(s||'').replace(/&nbsp;|&#160;/g,' ').replace(/&amp;|&#38;/g,'&').replace(/&quot;|&#34;/g,'"').replace(/&#8217;|&#039;|&rsquo;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(+n)).replace(/\s+/g,' ').trim();
const clean=s=>decode(String(s||'').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]*>/g,' '));
const out=[];
for(const p of posts){
 if(String(p.status)!=='publish'||!p.link)continue;
 const base=originals.find(x=>x._articleUrl.replace(/\/+$/,'')===String(p.link).replace(/\/+$/,''));if(!base)continue;
 let html=String(p.content?.rendered||p.content||'');
 const marker=html.search(/<article\b[^>]*class=["'][^"']*(?:lx-art|entry-content)/i);
 if(marker>=0){html=html.slice(marker);const close=html.indexOf('</article>');if(close>0)html=html.slice(0,close);}
 html=html.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'');
 const h2re=/<h2\b[^>]*>([\s\S]*?)<\/h2>/gi,heads=[...html.matchAll(h2re)];
 const sections=[];
 for(let k=0;k<heads.length;k++){
  const title=clean(heads[k][1]);if(!title||/takeaways|sources|about the author|your turn|frequently asked|related articles|get started/i.test(title))continue;
  const before=(heads[k].index||0)+heads[k][0].length;
  const until=k+1<heads.length?(heads[k+1].index||html.length):html.length;
  const block=html.slice(before,until);
  const p=block.match(/<p\b[^>]*>([\s\S]*?)<\/p>/i);
  const summary=clean(p?.[1]||'');
  if(summary.length>=36)sections.push({title:title.slice(0,110),summary:summary.slice(0,220)});
 }
 const body=clean(html).slice(0,9000);
 if(body.length<450||sections.length<3)continue;
 out.push({json:{...base,_wpPostId:p.id,_articleTitle:clean(p.title?.rendered||p.title||base._headline),_articleExcerpt:clean(p.excerpt?.rendered||p.excerpt||'').slice(0,200),_sections:sections.slice(0,7),_bodyLength:body.length}});
}
return out;

const out=[];
const limit=$('Select Two Published Articles').first().json._available||2;
const trim=(s,n)=>{s=String(s||'').replace(/\s+/g,' ').trim();if(s.length<=n)return s;let x=s.slice(0,n+1);return x.slice(0,x.lastIndexOf(' ')).replace(/[,:;\s]+$/,'')||s.slice(0,n);};

const complete=(input,n)=>{
 const s=String(input||'').replace(/\s+/g,' ').trim();
 if(!s)return '';
 const full=s.match(/^(.+?[.!?])(?:\s|$)/);
 const sentence=full?full[1]:s;
 if(sentence.length<=n)return sentence;
 const candidates=[' — ',': ','; ', ', ',' and ',' but ',' with ',' while '];
 let best='',bestIx=Infinity;
 for(const delimiter of candidates){
  const ix=sentence.indexOf(delimiter);
  if(ix>=52&&ix<=n&&ix<bestIx){best=sentence.slice(0,ix);bestIx=ix;}
 }
 if(best)return best.replace(/[,:;\s-]+$/,'')+'.';
 const boundary=sentence.slice(0,n-1).lastIndexOf(' ');
 if(boundary>=40)return sentence.slice(0,boundary).replace(/[,:;\s-]+$/,'')+'…';
 return sentence.slice(0,n-1).replace(/[,:;\s-]+$/,'')+'…';
};

const avoid=/\b(?:homelab|credential|secret|password|API.?key|private IP|internal subnet|VM\d{2,}|10\.\d+\.\d+|192\.168\.)\b/i;
for(const a of $input.all().map(i=>i.json)){
 if(out.length>=limit)break;
 if(!Array.isArray(a._sections)||a._sections.length<3)continue;
 const safe=a._sections.filter(s=>!avoid.test(s.summary)&&!avoid.test(s.title));
 if(safe.length<3)continue;
 const stages=safe.slice(0,4).map((s,i)=>({
  number:String(i+1).padStart(2,'0'),
  title:trim(s.title,54).toUpperCase(),
  description:/\b(?:never|guaranteed|always|no .*ever)\b/i.test(s.summary)?'The article examines this feature and its implications for privacy and reliability.':complete(s.summary,120)
 }));
 if(stages.length<3)continue;
 const title=trim(a._articleTitle,118);
 const styleFamilies=['systems map','editorial knowledge cards','architectural flow','practical briefing'];
 const family=styleFamilies[(Array.from(a._articleUrl).reduce((n,c)=>n+c.charCodeAt(0),0)%styleFamilies.length)];
 const design={
  width:1080,height:1350,brand:'LAUNCH AI WORKS',
  headline:title,eyebrow:'INSIGHTS / REAL WORKFLOW',
  subhead:/\b(?:never|guaranteed|always|without sending any|no .*ever)\b/i.test(a._articleExcerpt||'')?'A practical look at this tool, its workflow, and the questions worth asking.':complete(a._articleExcerpt||'An article explained through the practical ideas it covers.',125),
  steps:stages,look:family,footer:'LAUNCHAIWORKS.COM'
 };
 const fb='One useful article, turned into a visual explainer.\n\n'+title+'\n\nThis diagram breaks down '+stages.map(s=>s.title.toLowerCase()).join(' • ')+'.\n\nWe explore practical AI systems and automation at Launch AI Works. What would you want to understand or automate first?\n\n👉 https://launchaiworks.com\n🔗 Read more: '+a._articleUrl;
 let x='Visual explainer: '+trim(title,76)+'. '+stages.slice(0,2).map(s=>s.title.toLowerCase()).join(' → ')+'. 👉 https://launchaiworks.com '+a._articleUrl;
 const weighted=s=>s.replace(/https?:\/\/\S+/g,'x'.repeat(23)).length;
 if(weighted(x)>270)x='Visual explainer: '+trim(title,68)+'. 👉 https://launchaiworks.com '+a._articleUrl;
 if(weighted(x)>280)continue;
 out.push({json:{...a,_design:design,_steps:stages,_copyFacebook:fb,_copyX:x,_renderTemplate:family}});
}
return out;

const src=$('Build Exact Branded HTML').all().map(i=>i.json),out=[];
for(let i=0;i<$input.all().length;i++){
 const v=$input.all()[i];if(!v.binary?.image)continue;
 const bytes=await this.helpers.getBinaryDataBuffer(i,'image');
 if(bytes.length<30000||!bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))continue;
 const w=bytes.readUInt32BE(16),h=bytes.readUInt32BE(20);
 out.push({json:{success:true,format:'png',width:w,height:h,sizeBytes:bytes.length,base64:bytes.toString('base64')}});
}
return out;

const plans=$('Build LAIW Diagram Brief').all().map(i=>i.json);
const received=$input.all().map(i=>i.json),out=[];
for(let i=0;i<plans.length;i++){
 const resp=received[i]||{},plan=plans[i];if(resp.error||resp.success!==true||typeof resp.base64!=='string')continue;
 const b64=resp.base64;
 if(!/^[A-Za-z0-9+/=\s]+$/.test(b64)||b64.length<25000)continue;
 let bytes;try{bytes=Buffer.from(b64,'base64');}catch(e){continue}
 const png=bytes.length>100000&&bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));
 if(!png)continue;
 const w=bytes.readUInt32BE(16),h=bytes.readUInt32BE(20);
 if(w!==1080||h!==1350||bytes.length>12000000)continue;
 out.push({json:{...plan,imgBase64:b64,imgMime:'image/png',_renderBytes:bytes.length,_renderWidth:w,_renderHeight:h,_verified:true}});
}
return out;

const source=$('Verify Rendered PNG').all().map(i=>i.json);
const out=[];
for(const item of $input.all()){
 const f=item.binary?.data?.fileName||'';
 const p=source.find(s=>f.includes(s._queueId));
 if(!p||!item.binary?.data||p._verified!==true||p._renderWidth!==1080||p._renderHeight!==1350)continue;
 const j={...p};delete j.imgBase64;
 out.push({json:j,binary:item.binary});
}
return out;

const out=[];
for(const item of $input.all()){
 if(item.json._mode!=='draft_write_enabled')continue;
 out.push(item);
}
return out;

const available=$('Remove Base64 and Check Binary').all();
const now=$input.all().map(i=>i.json);
const urls=new Set(now.filter(x=>String(x.ContentTitle||'').startsWith('[Explainer]')).map(x=>String(x.ArticleURL||'').replace(/\/+$/,'')));
const ids=new Set(now.map(x=>String(x.QueueID||'')));
const key=available[0]?.json._targetDay;

const existingToday=now.filter(x=>String(x.ContentTitle||'').startsWith('[Explainer]')&&String(x.ScheduledFor||'').startsWith(key)&&!['Failed','Cancelled'].includes(String(x.Status||'')));
let occupied=existingToday.length;
const usedTimes=new Set(existingToday.map(x=>String(x.ScheduledFor||'').slice(11,16)));

const out=[];
for(const item of available){
 const x=item.json;
 if(x._mode!=='draft_write_enabled'||!item.binary?.data)continue;
 if(occupied>=2||ids.has(x._queueId)||urls.has(x._articleUrl.replace(/\/+$/,'')))continue;
 urls.add(x._articleUrl.replace(/\/+$/,''));ids.add(x._queueId);

const free=x._slotTimes.find(t=>!usedTimes.has(t));
 if(!free)continue;
 const scheduled=x._targetDay+' '+free;
 usedTimes.add(free);occupied++;

 out.push({json:{...x,_scheduledFor:scheduled,_fileName:'laiw-explainer-'+x._queueId+'.png'},binary:item.binary});
}
return out;

const files=$input.all().map(i=>i.json);
const plans=$('Fresh Queue Safety - Prepare Upload').all().map(i=>i.json);
const out=[];
for(const f of files){
 if(!f.id||!f.name)continue;
 const p=plans.find(x=>f.name.includes(x._queueId)||f.name.includes(x._fileName));
 if(!p)continue;
 out.push({json:{
 QueueID:p._queueId,
 ContentTitle:'[Explainer] '+p._articleTitle.slice(0,130),
 CopyFacebook:p._copyFacebook,
 CopyX:p._copyX,
 CopyYouTube:'',
 MediaDriveURL:'https://drive.google.com/uc?export=download&id='+f.id,
 MediaType:'image',Platforms:'FB,X',
 ScheduledFor:p._scheduledFor,
 Status:'Draft',
 FacebookURL:'',YouTubeURL:'',XURL:'',ErrorNotes:'',
 SourceURL:p._sourceUrl,
 ContentType:p._contentType,
 ArticleStatus:'Published',
 ArticleURL:p._articleUrl,
 ArticleNotes:'Branded explainer | Parent '+p._parentId+' | WordPress post '+p._wpPostId+' | '+p._renderTemplate+' | '+p._renderWidth+'x'+p._renderHeight+' | REVIEW EXACT IMAGE BEFORE APPROVAL'
 }});
}
return out;

const planned=$('Shape Draft Rows from Drive Upload').all().map(i=>i.json),current=$input.all().map(i=>i.json);
const ids=new Set(current.map(r=>String(r.QueueID||''))),articles=new Set(current.filter(r=>String(r.ContentTitle||'').startsWith('[Explainer]')).map(r=>String(r.ArticleURL||'').replace(/\/+$/,'')));
const out=[],claimed=new Set();
for(const p of planned){
 const day=String(p.ScheduledFor||'').slice(0,10);
 let count=current.filter(r=>String(r.ContentTitle||'').startsWith('[Explainer]')&&String(r.ScheduledFor||'').startsWith(day)&&!['Failed','Cancelled'].includes(String(r.Status||''))).length+out.filter(x=>x.json.ScheduledFor.startsWith(day)).length;
 if(count>=2||ids.has(p.QueueID)||articles.has(String(p.ArticleURL).replace(/\/+$/,''))||claimed.has(p.QueueID))continue;
 if(p.Status!=='Draft'||p.ArticleStatus!=='Published'||p.MediaType!=='image'||!p.MediaDriveURL.includes('drive.google.com/uc?export=download&id='))continue;
 if(!p.CopyFacebook.trimEnd().endsWith('🔗 Read more: '+p.ArticleURL)||!p.CopyX.trimEnd().endsWith(p.ArticleURL))continue;
 claimed.add(p.QueueID);out.push({json:p});
}
return out;
